import warnings, os, tempfile, gc
import click
from click.shell_completion import ShellComplete

def get_completions(cli, args, incomplete):
    comp = ShellComplete(cli, {}, cli.name, "_CLICK_COMPLETE")
    return comp.get_completions(args, incomplete)

def check(name, cli, args, incomplete):
    with tempfile.NamedTemporaryFile("w", suffix=".json", delete=False) as tf:
        tf.write("{}")
        fname = tf.name
    try:
        with warnings.catch_warnings(record=True) as w:
            warnings.simplefilter("always")
            get_completions(cli, args, incomplete)
            gc.collect()
        rws = [str(x.message) for x in w if issubclass(x.category, ResourceWarning)]
        print(f"{name}: {'LEAK: ' + str(rws) if rws else 'ok'}")
    finally:
        os.unlink(fname)
    return fname

# 1. simple command, file option
@click.command()
@click.option("--input", type=click.File("r"))
def cli1(input):
    pass
fname = check("file option", cli1, ["--input"], "")
check("file option complete value", cli1, ["--input", "/tmp/x"], "")

# 2. file argument
@click.command()
@click.argument("input", type=click.File("r"))
def cli2(input):
    pass
check("file argument", cli2, ["/tmp/nope.json"], "")

# 3. group with file option + subcommand
@click.group()
@click.option("--input", type=click.File("r"))
def grp(input):
    pass
@grp.command()
def sub():
    pass
check("group file opt, completing sub", grp, ["--input", "/tmp/x.json"], "")
check("group file opt, in sub", grp, ["--input", "/tmp/x.json", "sub"], "")

# 4. chained group with file option
@click.group(chain=True)
def chain():
    pass
@chain.command()
@click.option("--input", type=click.File("r"))
def set_(input):
    pass
@chain.command()
def start():
    pass
check("chain file opt", chain, ["set", "--input", "/tmp/x.json", "start"], "")

# 5. lazy file write (LazyFile)
@click.command()
@click.option("--out", type=click.File("w"))
def cli5(out):
    pass
check("lazy file write", cli5, ["--out", "/tmp/new.txt"], "")

# 6. multiple files
@click.command()
@click.option("--in1", type=click.File("r"))
@click.option("--in2", type=click.File("r"))
def cli6(in1, in2):
    pass
check("two file opts", cli6, ["--in1", "/tmp/a.json", "--in2", "/tmp/b.json"], "")
